toolCalls.commandLine:
"C:\\Program Files\\PowerShell\\7\\pwsh.exe" -Command "@'
const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
  await page.goto('http://127.0.0.1:3010/');
  await page.waitForTimeout(1000);
  console.log('sidebar before', await page.locator('.sidebar').evaluate(el => getComputedStyle(el).transform));
  await page.getByRole('button', { name: 'Menu' }).click();
  await page.waitForTimeout(500);
  console.log('sidebar after', await page.locator('.sidebar').evaluate(el => getComputedStyle(el).transform));
  console.log('fav box', await page.getByLabel('Marketplace navigation').getByRole('link', { name: /Favorites/ }).boundingBox());
  await browser.close();
})();
'@ | node -"

